mapper.select:
/* QuoteMapper.findQuoteByIdForUpdate */
SELECT QUT_SN, SVC_REQ_SN, USR_SN, QUT_AMT, QUT_CN,
       QUT_STATUS_CD, QUT_REVISE_CNT, QUT_REG_ID, QUT_UPDT_ID
  FROM QUOTE
 WHERE QUT_SN = #{qutSn}
FOR UPDATE

mapper.update:
/* QuoteMapper.updateQuote */
UPDATE QUOTE
   SET QUT_AMT        = #{req.amount},
       QUT_CN         = #{req.content},
       QUT_STATUS_CD  = 'QUTC0002',
       QUT_REVISE_CNT = QUT_REVISE_CNT + 1,
       QUT_UPDT_ID    = #{updtId}
 WHERE QUT_SN = #{qutSn}

/* QuoteMapper.withdrawQuote */
UPDATE QUOTE
   SET QUT_STATUS_CD = 'QUTC0005',
       QUT_UPDT_ID   = #{updtId}
 WHERE QUT_SN = #{qutSn}

mapper.select:
/* QuoteMapper.findMyQuotes */
SELECT q.QUT_SN, q.SVC_REQ_SN,
       q.QUT_AMT, q.QUT_CN, q.QUT_STATUS_CD, q.QUT_REVISE_CNT,
       q.QUT_REG_DT, q.QUT_UPDT_DT
  FROM QUOTE q
 WHERE q.USR_SN = #{usrSn}
 ORDER BY q.QUT_REG_DT DESC
 LIMIT #{size} OFFSET #{offset}

/* QuoteMapper.countMyQuotes */
SELECT COUNT(*)
  FROM QUOTE
 WHERE USR_SN = #{usrSn}

/* QuoteMapper.findQuoteHistory */
SELECT QUT_HST_SN, QUT_SN, QUT_HST_AMT, QUT_HST_CN, QUT_HST_REG_DT
  FROM QUOTE_HISTORY
 WHERE QUT_SN = #{qutSn}
 ORDER BY QUT_HST_REG_DT ASC
